          'زيادة النترات والفوسفات قد تسبب إثراءً غذائيًا مفرطًا (Eutrophication)، فتحدث زيادة في نمو الطحالب، ثم يؤدي تحلل كتلتها الحيوية إلى استهلاك الأكسجين وقد تظهر مناطق منخفضة الأكسجين.'
