          'عند ذوبان CO₂ في الماء يتكون جزء من حمض الكربونيك H₂CO₃، الذي يمكن أن يتفكك ويطلق أيونات الهيدروجين H⁺ وأيونات البيكربونات HCO₃⁻. هذه الاتزانات تؤثر في pH وكيمياء الكربونات في الماء.',
          'لا يتحول كل CO₂ الذائب إلى حمض كربونيك؛ فهناك صور كيميائية متزنة مختلفة، منها CO₂(aq) وH₂CO₃ وHCO₃⁻ وCO₃²⁻، وتتغير نسبها مع pH ودرجة الحرارة والقلوية.'
