          'Convection الحمل الحراري يحدث في السوائل والغازات نتيجة حركة المائع نفسه؛ فالجزء الذي يسخن يتمدد وتقل كثافته غالبًا فيرتفع، بينما يهبط الجزء الأبرد الأعلى كثافة، فتتكون تيارات حمل. هذا مهم في حركة الهواء والماء.',
          'Radiation الإشعاع ينقل الطاقة بموجات كهرومغناطيسية ولا يحتاج إلى وسط مادي؛ لذلك تصلنا طاقة الشمس عبر فراغ الفضاء. قد تعمل الطرق الثلاث معًا في نظام واحد، لكن لكل منها آلية مميزة.'
