        table: { headers: ['الطريقة', 'كيف تنتقل الطاقة؟', 'مثال'], rows: [['Conduction التوصيل', 'تصادم وتفاعل الجسيمات المتجاورة', 'سخونة مقبض معدني موصل للحرارة.'], ['Convection الحمل', 'حركة السائل أو الغاز نفسه', 'صعود الهواء الدافئ وهبوط الهواء الأبرد.'], ['Radiation الإشعاع', 'موجات كهرومغناطيسية', 'وصول حرارة الشمس إلى الأرض.']] },
