          'ينخفض الضغط الجزئي للأكسجين مع الارتفاع لأن الضغط الكلي ينخفض، رغم أن نسبة الأكسجين في الهواء الجاف تظل قريبة من 21% في الارتفاعات المعتادة. يقل فرق الضغط الذي يدفع الأكسجين للانتقال من الهواء إلى الدم، ولذلك قد يحتاج الجسم إلى التكيف وقد يشعر الشخص بالتعب أو ضيق النفس عند الارتفاعات الكبيرة.',
