          'تراقب محطات جودة الهواء تراكيز الملوثات، بينما تساعد الأقمار الصناعية وأجهزة الاستشعار والنماذج الجوية على متابعة السحب والهباء والغازات وانتقالها. البيانات لا تحل المشكلة وحدها، لكنها تساعد على تحديد المصادر، وإصدار التحذيرات، وتقييم أثر السياسات والحلول.'
