const existingTerms = new Set((window.SCIENCE_GLOSSARY || []).map(term => String(Array.isArray(term) ? term[0] : (term.en || term.english || '')).toLowerCase()));
for (const [en, ar, definition, example] of extraGlossary) {
  if (!existingTerms.has(en.toLowerCase())) window.SCIENCE_GLOSSARY.push([en, ar, definition, example]);
}

